[Form]
public class METPriceChangeInquiryBasePriceDialog extends FormRun
{
    private METGeneratePriceChangeInquiryBasePriceDialog dialog;

}

public void init()
{
    if (!this.args() || !this.args().caller())
    {
        throw error(strfmt("@SYS22862", element.name()));
    }

    dialog = element.args().caller().runbase();
    element.activationDate(true, GUPBasePriceVersion::findLatest().LastActivation);
    element.interval(true, 1);

    super();

}

edit METPriceChangeInquiryItemNumber itemId(
    boolean                             _set,
    METPriceChangeInquiryItemNumber     _itemId)
{
    if (_set)
    {
        METPriceChangeInquiryItemNumber prevValue = dialog.parmItemId();
        dialog.parmItemId(GUPPricingAttributeConditionValueHelper::appendConditionValue(_itemId, prevValue));
    }

    return dialog.parmItemId();
}

edit METPriceChangeInquirySite custSiteId(
    boolean                     _set,
    METPriceChangeInquirySite   _custSiteId)
{
    if (_set)
    {
        METPriceChangeInquirySite prevValue = dialog.parmSiteId();
        dialog.parmSiteId(GUPPricingAttributeConditionValueHelper::appendConditionValue(_custSiteId, prevValue));
    }

    return dialog.parmSiteId();
}

edit METPriceChangeInquiryActivationDate activationDate(
    boolean                                 _set,
    METPriceChangeInquiryActivationDate     _date)
{
    if (_set)
    {
        dialog.parmActivationDate(_date);
    }

    return dialog.parmActivationDate();
}

edit METPriceChangeInquiryInterval interval(
    boolean                           _set,
    METPriceChangeInquiryInterval     _interval)
{
    if (_set)
    {
        dialog.parmInterval(_interval);
    }

    return dialog.parmInterval();
}

public void lookup()
{
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(InventTable), this);
    Query                   query = new Query();
    QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(InventTable));

    sysTableLookup.addLookupfield(fieldNum(InventTable, ItemId));
    sysTableLookup.addLookupfield(fieldNum(InventTable, NameAlias));
    sysTableLookup.addLookupfield(fieldNum(InventTable, ItemType));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

public void lookup()
{
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(InventSite), this);
    Query                   query = new Query();
    QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(InventSite));

    sysTableLookup.addLookupfield(fieldNum(InventSite, SiteId));
    sysTableLookup.addLookupfield(fieldNum(InventSite, Name));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

public boolean validate()
{
    boolean ret = super();

    if (this.value() > 30 || this.value() <= 0)
    {
        ret = ret && checkFailed("@GlobalUnifiedPricingMetcash:METPriceChangeInquiryInterval_Validation");
    }

    return ret;
}
